// Christmas Advent Surprise — Daily Gift Discovery
// Pure Canvas 2D. 25 seconds, two 12.5-second scenes, 16:9, scalable to 4K.
// COPY is the reserved buyer text area in a 1920x1080 reference layout.
// Artwork and scene transitions are restricted to GROUPS.
// Export target: 3840x2160, 60 fps, 100 Mbps. Set bitrate in your encoder.
function draw(ctx, time, width, height) {
  const C = {
    "bg": "#F5F0E6",
    "bg2": "#F5F0E6",
    "paper": "#FFF9EE",
    "soft": "#E5E9DC",
    "accent": "#A43C47",
    "forest": "#315847",
    "ink": "#2F4338",
    "muted": "#798174",
    "line": "#CED8C8",
    "gold": "#BD9F5C",
    "ribbon": "#8D303D",
    "kraft": "#D5BA92"
  };
  const COPY = {"x": 126, "y": 160, "w": 864, "h": 760};
  const GROUPS = [{"x": 1098, "y": 151, "w": 696, "h": 774}];
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  if (!ctx || !Number.isFinite(t) || t < 0 || width <= 0 || height <= 0) return;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const phase = (loopT / duration) * Math.PI * 2;
  const local = sceneProgress * sceneDuration;
  const FONT = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (v) => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const wave = (cycles = 1, offset = 0) => Math.sin(phase * cycles + offset);

  function rr(x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function rect(x, y, w, h, r, fill, stroke = null, lw = 2.5) {
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke = null, lw = 2.5) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function polygon(points, fill, stroke = null, lw = 2.5) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color = C.ink, lw = 2.5) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function grad(x, y, w, h, a, b) {
    const g = ctx.createLinearGradient(x, y, x + w * 0.3, y + h);
    g.addColorStop(0, a); g.addColorStop(1, b); return g;
  }
  function text(str, x, y, size, color = C.ink, weight = 600, maxWidth = 1600, align = 'left') {
    ctx.font = weight + ' ' + size + 'px ' + FONT;
    const measured = ctx.measureText(str).width;
    if (measured > maxWidth) size *= maxWidth / measured;
    ctx.font = weight + ' ' + size + 'px ' + FONT;
    ctx.textAlign = align; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    ctx.fillText(str, x, y);
  }
  function caps(str, x, y, size = 17, color = C.muted, maxWidth = 700, tracking = 2.0) {
    ctx.font = '700 ' + size + 'px ' + FONT;
    let total = ctx.measureText(str).width + tracking * Math.max(0, str.length - 1);
    if (total > maxWidth) { const f = maxWidth / total; size *= f; tracking *= f; }
    ctx.font = '700 ' + size + 'px ' + FONT;
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    let cursor = x;
    for (let i = 0; i < str.length; i++) {
      ctx.fillText(str[i], cursor, y); cursor += ctx.measureText(str[i]).width + tracking;
    }
  }
  function panel(x, y, w, h, color = C.paper, radius = 26, outline = C.line) {
    rect(x + 7, y + 10, w, h, radius, 'rgba(30,39,33,0.07)');
    rect(x, y, w, h, radius, color, outline, 2.2);
  }
  function place(x, y, angle, fn) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle); fn(); ctx.restore();
  }
  function reveal(delay, fn, distance = 26) {
    const a = ease((local - delay) / 1.15);
    ctx.save(); ctx.globalAlpha *= a; ctx.translate(0, distance * (1 - a)); fn(); ctx.restore();
  }
  function chip(x, y, w, title, color = C.accent) {
    rect(x, y, w, 42, 21, C.soft);
    ellipse(x + 21, y + 21, 4, 4, color);
    caps(title, x + 36, y + 27, 15, color, w - 55, 1.4);
  }
  function star(x, y, r, color = C.accent, angle = 0, points = 4) {
    const vertices = [];
    for (let i = 0; i < points * 2; i++) {
      const a = angle - Math.PI / 2 + i * Math.PI / points;
      const rad = i % 2 === 0 ? r : r * (points === 4 ? 0.26 : 0.48);
      vertices.push([x + Math.cos(a) * rad, y + Math.sin(a) * rad]);
    }
    polygon(vertices, color);
  }
  function arrow(x, y, color = C.paper, size = 13) {
    line(x - size, y, x + size, y, color, 2.8);
    line(x + size - 8, y - 8, x + size, y, color, 2.8);
    line(x + size - 8, y + 8, x + size, y, color, 2.8);
  }
  function button(x, y, w, title, inverse = false) {
    const fill = inverse ? C.paper : C.accent;
    const ink = inverse ? C.ink : C.paper;
    rect(x + 4, y + 7, w, 76, 18, 'rgba(27,39,32,0.08)');
    rect(x, y, w, 76, 18, fill);
    text(title, x + 28, y + 47, 23, ink, 700, w - 100);
    arrow(x + w - 43 + 4 * wave(2, 0.3), y + 38, ink);
  }
  function check(x, y, radius = 18, fill = C.forest) {
    ellipse(x, y, radius, radius, fill);
    line(x - radius * 0.43, y, x - radius * 0.1, y + radius * 0.33, C.paper, 3);
    line(x - radius * 0.1, y + radius * 0.33, x + radius * 0.46, y - radius * 0.37, C.paper, 3);
  }
  function ornament(x, top, y, r, color = C.accent, angle = 0) {
    place(x, top, angle, () => {
      line(0, 0, 0, y - top - r - 10, C.line, 2);
      rect(-7, y - top - r - 10, 14, 10, 3, C.ink);
      ellipse(0, y - top, r, r, color, C.ink, 2.5);
      line(-r * 0.55, y - top - r * 0.36, r * 0.55, y - top - r * 0.36, C.paper, 3);
      line(-r * 0.73, y - top, r * 0.73, y - top, C.paper, 3);
      line(-r * 0.55, y - top + r * 0.36, r * 0.55, y - top + r * 0.36, C.paper, 3);
    });
  }
  function leaf(x, y, size = 30, angle = 0, color = C.forest) {
    place(x, y, angle, () => {
      ctx.beginPath(); ctx.moveTo(0, size * 0.65);
      ctx.bezierCurveTo(-size * 0.65, 0, -size * 0.42, -size * 0.75, 0, -size);
      ctx.bezierCurveTo(size * 0.5, -size * 0.62, size * 0.6, 0, 0, size * 0.65);
      ctx.closePath(); ctx.fillStyle = color; ctx.fill();
      line(0, size * 0.38, 0, -size * 0.65, C.paper, 1.7);
    });
  }
  function ground(x, y, w, color = C.line) { rect(x, y, w, 13, 6, color); }


  function gift(x, y, w, h, body = C.accent, ribbon = C.paper) {
    const u = w / 200;
    rect(x + 6, y + 8, w, h, 10 * u, 'rgba(25,38,31,0.08)');
    rect(x, y, w, h, 10 * u, grad(x, y, w, h, body, body), C.ink, 2.6);
    rect(x + w * 0.425, y + 1, w * 0.15, h - 2, 0, ribbon);
    const center = x + w / 2;
    ctx.beginPath(); ctx.moveTo(center, y - 17 * u);
    ctx.bezierCurveTo(center - 60 * u, y - 27 * u, center - 74 * u, y - 88 * u, center - 20 * u, y - 60 * u);
    ctx.bezierCurveTo(center - 6 * u, y - 49 * u, center - 3 * u, y - 32 * u, center, y - 17 * u);
    ctx.closePath(); ctx.fillStyle = ribbon; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.4; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(center, y - 17 * u);
    ctx.bezierCurveTo(center + 60 * u, y - 27 * u, center + 74 * u, y - 88 * u, center + 20 * u, y - 60 * u);
    ctx.bezierCurveTo(center + 6 * u, y - 49 * u, center + 3 * u, y - 32 * u, center, y - 17 * u);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    rect(x - 6 * u, y - 20 * u, w + 12 * u, 27 * u, 6 * u, body, C.ink, 2.6);
    rect(center - w * 0.075, y - 19 * u, w * 0.15, 25 * u, 0, ribbon);
    ellipse(center, y - 29 * u, 11 * u, 10 * u, ribbon, C.ink, 2.2);
  }

  // The flat background and COPY rectangle remain untouched throughout the loop.
  // All foreground artwork, including transitions, stays inside GROUPS.
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent'; ctx.setLineDash([]);
  ctx.fillStyle = C.bg; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2); ctx.scale(scale, scale); ctx.translate(-960, -540);
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.beginPath();
  for (const g of GROUPS) ctx.rect(g.x, g.y, g.w, g.h);
  ctx.clip();
  for (const g of GROUPS) {
    ctx.save(); ctx.globalAlpha = 0.60;
    ellipse(g.x + g.w / 2, g.y + g.h / 2, g.w * 0.475, g.h * 0.405, C.soft);
    ctx.restore();
  }


  function adventBoard(x, y, compact = false) {
    const rows = compact ? 2 : 4;
    const boardHeight = compact ? 296 : 534;
    panel(x, y, 638, boardHeight, C.paper, 27);
    caps('THE ADVENT EDIT', x + 36, y + 48, 19, C.ink, 551, 2);
    const cellW = 80, cellH = compact ? 65 : 84;
    const startY = y + 79;
    const openCells = [4, 10, 16];
    for (let i = 0; i < rows * 6; i++) {
      const xx = x + 43 + (i % 6) * 94;
      const yy = startY + Math.floor(i / 6) * (cellH + 13);
      rect(xx, yy, cellW, cellH, 10, C.soft, C.ink, 1.9);
      const sequence = openCells.indexOf(i);
      const a = compact || sequence < 0 ? 0 : 0.94 * ease((local - 1.7 - sequence * 0.55) / 1.65);
      if (a > 0) star(xx + 64, yy + cellH / 2, 11, C.gold, 0, 5);
      const projected = cellW * Math.cos(a);
      rect(xx, yy, projected, cellH, 9, i % 3 === 0 ? C.forest : C.accent, C.ink, 1.9);
      text(String(i + 1), xx + projected / 2, yy + cellH / 2 + 9, 26, C.paper, 700, projected - 12, 'center');
    }
    caps(compact ? 'A NEW LITTLE DISCOVERY' : 'DAILY LITTLE SURPRISES', x + 37, y + boardHeight - 27, 15, C.muted, 558, 1.7);
  }
  if (currentScene === 0) {
    reveal(0.12, () => adventBoard(1127, 242), 18);
    reveal(0.4, () => {
      gift(1180, 860 + 2 * wave(2, 0.6), 132, 42, C.accent, C.paper);
      gift(1403, 863 + 2 * wave(2, 1.6), 132, 40, C.forest, C.gold);
      star(1692, 866 + 2 * wave(1), 22, C.gold, 0.02 * wave(1), 4);
    }, 10);
  } else {
    reveal(0.13, () => adventBoard(1127, 232, true), 18);
    reveal(0.42, () => {
      gift(1298, 686 + 3 * wave(1, 1.3), 267, 176, C.accent, C.paper);
      ground(1274, 885, 317);
      panel(1142, 642, 104, 152, C.paper, 17, C.ink);
      star(1194, 690, 20, C.gold, 0, 5);
      text('JOY', 1194, 746, 21, C.ink, 700, 82, 'center');
      panel(1642, 642, 104, 152, C.forest, 17, C.ink);
      star(1694, 691, 20, C.paper, 0, 4);
      text('GIFT', 1694, 747, 21, C.paper, 700, 82, 'center');
    }, 12);
  }
  ornament(1726, 171, 205, 18, C.accent, 0.008 * wave(1, 0.4));
  star(1150, 197 + 3 * wave(1, 1.2), 16, C.gold, 0, 4);


  // A wrapping-paper wipe is restricted to each illustration group.
  // There is no full-frame transition over the buyer's copy space.
  const wipeDuration = 1.1;
  const closeStart = sceneDuration - wipeDuration;
  if (local < wipeDuration || local > closeStart) {
    const opening = local < wipeDuration;
    const progress = opening ? ease(local / wipeDuration) : ease((local - closeStart) / wipeDuration);
    for (const g of GROUPS) {
      const left = opening ? g.x + g.w * progress : g.x;
      const right = opening ? g.x + g.w : g.x + g.w * progress;
      ctx.save(); rr(g.x, g.y, g.w, g.h, Math.min(28, g.h / 3)); ctx.clip();
      ctx.beginPath(); ctx.rect(left, g.y, Math.max(0, right - left), g.h); ctx.clip();
      ctx.fillStyle = C.accent; ctx.fillRect(g.x, g.y, g.w, g.h);
      const drift = 18 * wave(1);
      for (let i = -3; i < 5; i++) {
        const x = g.x + i * 170 + drift;
        polygon([[x, g.y - 45], [x + 35, g.y - 45], [x + g.h * 0.43 + 35, g.y + g.h + 45], [x + g.h * 0.43, g.y + g.h + 45]], C.ribbon);
      }
      ctx.restore();
    }
  }
  ctx.restore();
}

// Christmas Wishlist — Save Your Favourite Gifts
// Pure Canvas 2D. 25 seconds, two 12.5-second scenes, 16:9, scalable to 4K.
// COPY is the reserved buyer text area in a 1920x1080 reference layout.
// Artwork and scene transitions are restricted to GROUPS.
// Export target: 3840x2160, 60 fps, 100 Mbps. Set bitrate in your encoder.
function draw(ctx, time, width, height) {
  const C = {
    "bg": "#F1F1E8",
    "bg2": "#F1F1E8",
    "paper": "#FFFCF4",
    "soft": "#DFE8D8",
    "accent": "#B96659",
    "forest": "#526F53",
    "ink": "#314934",
    "muted": "#778270",
    "line": "#CDD9C8",
    "gold": "#BC9F5D",
    "ribbon": "#A45649",
    "kraft": "#D5BA92"
  };
  const COPY = {"x": 910, "y": 160, "w": 884, "h": 760};
  const GROUPS = [{"x": 126, "y": 151, "w": 676, "h": 774}];
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  if (!ctx || !Number.isFinite(t) || t < 0 || width <= 0 || height <= 0) return;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const phase = (loopT / duration) * Math.PI * 2;
  const local = sceneProgress * sceneDuration;
  const FONT = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const ease = (v) => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const wave = (cycles = 1, offset = 0) => Math.sin(phase * cycles + offset);

  function rr(x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function rect(x, y, w, h, r, fill, stroke = null, lw = 2.5) {
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke = null, lw = 2.5) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function polygon(points, fill, stroke = null, lw = 2.5) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color = C.ink, lw = 2.5) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function grad(x, y, w, h, a, b) {
    const g = ctx.createLinearGradient(x, y, x + w * 0.3, y + h);
    g.addColorStop(0, a); g.addColorStop(1, b); return g;
  }
  function text(str, x, y, size, color = C.ink, weight = 600, maxWidth = 1600, align = 'left') {
    ctx.font = weight + ' ' + size + 'px ' + FONT;
    const measured = ctx.measureText(str).width;
    if (measured > maxWidth) size *= maxWidth / measured;
    ctx.font = weight + ' ' + size + 'px ' + FONT;
    ctx.textAlign = align; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    ctx.fillText(str, x, y);
  }
  function caps(str, x, y, size = 17, color = C.muted, maxWidth = 700, tracking = 2.0) {
    ctx.font = '700 ' + size + 'px ' + FONT;
    let total = ctx.measureText(str).width + tracking * Math.max(0, str.length - 1);
    if (total > maxWidth) { const f = maxWidth / total; size *= f; tracking *= f; }
    ctx.font = '700 ' + size + 'px ' + FONT;
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
    let cursor = x;
    for (let i = 0; i < str.length; i++) {
      ctx.fillText(str[i], cursor, y); cursor += ctx.measureText(str[i]).width + tracking;
    }
  }
  function panel(x, y, w, h, color = C.paper, radius = 26, outline = C.line) {
    rect(x + 7, y + 10, w, h, radius, 'rgba(30,39,33,0.07)');
    rect(x, y, w, h, radius, color, outline, 2.2);
  }
  function place(x, y, angle, fn) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle); fn(); ctx.restore();
  }
  function reveal(delay, fn, distance = 26) {
    const a = ease((local - delay) / 1.15);
    ctx.save(); ctx.globalAlpha *= a; ctx.translate(0, distance * (1 - a)); fn(); ctx.restore();
  }
  function chip(x, y, w, title, color = C.accent) {
    rect(x, y, w, 42, 21, C.soft);
    ellipse(x + 21, y + 21, 4, 4, color);
    caps(title, x + 36, y + 27, 15, color, w - 55, 1.4);
  }
  function star(x, y, r, color = C.accent, angle = 0, points = 4) {
    const vertices = [];
    for (let i = 0; i < points * 2; i++) {
      const a = angle - Math.PI / 2 + i * Math.PI / points;
      const rad = i % 2 === 0 ? r : r * (points === 4 ? 0.26 : 0.48);
      vertices.push([x + Math.cos(a) * rad, y + Math.sin(a) * rad]);
    }
    polygon(vertices, color);
  }
  function arrow(x, y, color = C.paper, size = 13) {
    line(x - size, y, x + size, y, color, 2.8);
    line(x + size - 8, y - 8, x + size, y, color, 2.8);
    line(x + size - 8, y + 8, x + size, y, color, 2.8);
  }
  function button(x, y, w, title, inverse = false) {
    const fill = inverse ? C.paper : C.accent;
    const ink = inverse ? C.ink : C.paper;
    rect(x + 4, y + 7, w, 76, 18, 'rgba(27,39,32,0.08)');
    rect(x, y, w, 76, 18, fill);
    text(title, x + 28, y + 47, 23, ink, 700, w - 100);
    arrow(x + w - 43 + 4 * wave(2, 0.3), y + 38, ink);
  }
  function check(x, y, radius = 18, fill = C.forest) {
    ellipse(x, y, radius, radius, fill);
    line(x - radius * 0.43, y, x - radius * 0.1, y + radius * 0.33, C.paper, 3);
    line(x - radius * 0.1, y + radius * 0.33, x + radius * 0.46, y - radius * 0.37, C.paper, 3);
  }
  function ornament(x, top, y, r, color = C.accent, angle = 0) {
    place(x, top, angle, () => {
      line(0, 0, 0, y - top - r - 10, C.line, 2);
      rect(-7, y - top - r - 10, 14, 10, 3, C.ink);
      ellipse(0, y - top, r, r, color, C.ink, 2.5);
