    rect(x + w * 0.425, y + 1, w * 0.15, h - 2, 0, ribbon);
    const center = x + w / 2;
    ctx.beginPath(); ctx.moveTo(center, y - 17 * u);
    ctx.bezierCurveTo(center - 60 * u, y - 27 * u, center - 74 * u, y - 88 * u, center - 20 * u, y - 60 * u);
    ctx.bezierCurveTo(center - 6 * u, y - 49 * u, center - 3 * u, y - 32 * u, center, y - 17 * u);
    ctx.closePath(); ctx.fillStyle = ribbon; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.4; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(center, y - 17 * u);
    ctx.bezierCurveTo(center + 60 * u, y - 27 * u, center + 74 * u, y - 88 * u, center + 20 * u, y - 60 * u);
    ctx.bezierCurveTo(center + 6 * u, y - 49 * u, center + 3 * u, y - 32 * u, center, y - 17 * u);
    ctx.closePath(); ctx.fill(); ctx.stroke();
    rect(x - 6 * u, y - 20 * u, w + 12 * u, 27 * u, 6 * u, body, C.ink, 2.6);
    rect(center - w * 0.075, y - 19 * u, w * 0.15, 25 * u, 0, ribbon);
    ellipse(center, y - 29 * u, 11 * u, 10 * u, ribbon, C.ink, 2.2);
  }

  function envelope(x, y, w, h, color = C.accent) {
    rect(x, y, w, h, 14, color, C.ink, 2.7);
    polygon([[x + 2, y + 2], [x + w / 2, y + h * 0.59], [x + w - 2, y + 2]], C.soft, C.ink, 2.7);
    line(x + 4, y + h - 5, x + w * 0.34, y + h * 0.53, C.ink, 2.4);
    line(x + w - 4, y + h - 5, x + w * 0.66, y + h * 0.53, C.ink, 2.4);
    ellipse(x + w / 2, y + h * 0.59, 20, 20, C.paper); star(x + w / 2, y + h * 0.59, 13, C.accent, 0, 4);
  }

  function heart(x, y, s = 1, color = C.accent) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ctx.beginPath(); ctx.moveTo(0, 33);
    ctx.bezierCurveTo(-54, 0, -44, -35, -19, -31);
    ctx.bezierCurveTo(-6, -30, 0, -18, 0, -18);
    ctx.bezierCurveTo(0, -18, 6, -30, 19, -31);
    ctx.bezierCurveTo(44, -35, 54, 0, 0, 33);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 2.2; ctx.stroke();
    ctx.restore();
  }

  // The flat background and COPY rectangle remain untouched throughout the loop.
  // All foreground artwork, including transitions, stays inside GROUPS.
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'transparent'; ctx.setLineDash([]);
  ctx.fillStyle = C.bg; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2); ctx.scale(scale, scale); ctx.translate(-960, -540);
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.beginPath();
  for (const g of GROUPS) ctx.rect(g.x, g.y, g.w, g.h);
  ctx.clip();
  for (const g of GROUPS) {
    ctx.save(); ctx.globalAlpha = 0.60;
    ellipse(g.x + g.w / 2, g.y + g.h / 2, g.w * 0.475, g.h * 0.405, C.soft);
    ctx.restore();
  }


  function thankYouEnvelope(x, y, w, h, pull) {
    polygon([[x, y], [x + w / 2, y - h * 0.67], [x + w, y]], C.soft, C.ink, 2.7);
    rect(x, y, w, h, 16, C.accent, C.ink, 2.7);
    const cy = y - 52 - 93 * pull;
    panel(x + 30, cy, w - 60, 219, C.paper, 17, C.ink);
    text('THANK YOU', x + w / 2, cy + 76, 37, C.ink, 700, w - 111, 'center');
    text('FOR A WONDERFUL YEAR', x + w / 2, cy + 113, 19, C.muted, 600, w - 111, 'center');
    line(x + 91, cy + 150, x + w - 91, cy + 150, C.line, 2);
    star(x + w - 94, cy + 39, 11, C.gold, 0, 4);
    polygon([[x, y + 2], [x + w / 2, y + h * 0.43], [x + w, y + 2], [x + w, y + h - 2], [x, y + h - 2]], grad(x, y, w, h, C.accent, C.ribbon), C.ink, 2.7);
    line(x + 3, y + h - 7, x + w * 0.31, y + h * 0.51, C.ink, 2.2);
    line(x + w - 3, y + h - 7, x + w * 0.69, y + h * 0.51, C.ink, 2.2);
    ellipse(x + w / 2, y + h * 0.43, 23, 23, C.paper, C.ink, 2.2);
    star(x + w / 2, y + h * 0.43, 14, C.accent, 0, 4);
  }
  if (currentScene === 0) {
    reveal(0.12, () => {
      panel(1186, 216, 578, 73, C.paper, 21);
      caps('THE CHRISTMAS THANK YOU', 1218, 263, 18, C.ink, 506, 1.7);
      const pull = ease((local - 1.7) / 2.5);
      thankYouEnvelope(1194, 662, 546, 181, pull);
    }, 14);
    reveal(0.31, () => {
      place(1245, 303, 0.009 * wave(1, 0.3), () => {
        line(0, 0, 0, 54, C.line, 2);
        panel(-59, 53, 118, 127, C.paper, 17, C.ink);
        text('JOY', 0, 106, 24, C.ink, 700, 89, 'center');
        star(0, 144, 16, C.gold, 0, 4);
      });
      panel(1678, 354, 86, 143, C.forest, 17, C.ink);
      heart(1721, 399, 0.50, C.paper);
      leaf(1721, 455, 18, 0, C.paper);
    }, 10);
  } else {
    reveal(0.12, () => {
      panel(1186, 257, 578, 283, C.paper, 27);
      star(1475, 307, 14, C.gold, 0, 4);
      text('THANK YOU', 1475, 383, 57, C.ink, 700, 502, 'center');
      text('FOR A WONDERFUL YEAR', 1475, 427, 20, C.muted, 600, 498, 'center');
      line(1279, 463, 1671, 463, C.line, 2);
      heart(1475, 501, 0.33, C.accent);
    }, 16);
    reveal(0.35, () => {
      gift(1198, 729 + 2.5 * wave(1, 0.5), 224, 153, C.accent, C.paper);
      envelope(1517, 718 + 2.5 * wave(1, 1.7), 220, 137, C.forest);
      ground(1180, 909, 260); ground(1498, 879, 260);
      leaf(1475, 613, 28, 0.4 + 0.008 * wave(1, 1.2));
    }, 10);
  }
  star(1730, 183 + 2.5 * wave(1, 0.8), 16, C.gold, phase, 4);


  // A wrapping-paper wipe is restricted to each illustration group.
  // There is no full-frame transition over the buyer's copy space.
  const wipeDuration = 1.1;
  const closeStart = sceneDuration - wipeDuration;
  if (local < wipeDuration || local > closeStart) {
    const opening = local < wipeDuration;
    const progress = opening ? ease(local / wipeDuration) : ease((local - closeStart) / wipeDuration);
    for (const g of GROUPS) {
      const left = opening ? g.x + g.w * progress : g.x;
      const right = opening ? g.x + g.w : g.x + g.w * progress;
      ctx.save(); rr(g.x, g.y, g.w, g.h, Math.min(28, g.h / 3)); ctx.clip();
      ctx.beginPath(); ctx.rect(left, g.y, Math.max(0, right - left), g.h); ctx.clip();
      ctx.fillStyle = C.accent; ctx.fillRect(g.x, g.y, g.w, g.h);
      const drift = 18 * wave(1);
      for (let i = -3; i < 5; i++) {
        const x = g.x + i * 170 + drift;
        polygon([[x, g.y - 45], [x + 35, g.y - 45], [x + g.h * 0.43 + 35, g.y + g.h + 45], [x + g.h * 0.43, g.y + g.h + 45]], C.ribbon);
      }
      ctx.restore();
    }
  }
  ctx.restore();
}
